import React, { useState, useEffect } from 'react';
import { Chart } from 'primereact/chart';

export default function Radar() {
    const [chartData, setChartData] = useState({});
    const [chartOptions, setChartOptions] = useState({});

    useEffect(() => {
        const targetElement = document.body ?? document.documentElement;
        const documentStyle = getComputedStyle(targetElement);
        const getColor = (variable) => {
            const value = documentStyle.getPropertyValue(variable)?.trim();
            if (value) {
                return value;
            }
            const rootStyle = getComputedStyle(document.documentElement);
            const rootValue = rootStyle.getPropertyValue(variable)?.trim();
            return rootValue;
        };
        const textColor = getColor('--uls-text-color');
        const textColorSecondary = getColor('--uls-secondary-text-color');
        const data = {
            labels: ['Eating', 'Drinking', 'Sleeping', 'Designing', 'Coding', 'Cycling', 'Running'],
            datasets: [
                {
                    label: 'My First dataset',
                    borderColor: getColor('--uls-primary-color'),
                    pointBackgroundColor: getColor('--uls-primary-color'),
                    pointBorderColor: getColor('--uls-primary-color'),
                    pointHoverBackgroundColor: textColor,
                    pointHoverBorderColor: getColor('--uls-primary-color'),
                    data: [65, 59, 90, 81, 56, 55, 40]
                },
                {
                    label: 'My Second dataset',
                    borderColor: getColor('--uls-warning-color'),
                    pointBackgroundColor: getColor('--uls-warning-color'),
                    pointBorderColor: getColor('--uls-warning-color'),
                    pointHoverBackgroundColor: textColor,
                    pointHoverBorderColor: getColor('--uls-warning-color'),
                    data: [28, 48, 40, 19, 96, 27, 100]
                }
            ]
        };
        const options = {
            plugins: {
                legend: {
                    labels: {
                        color: textColor
                    }
                }
            },
            scales: {
                r: {
                    grid: {
                        color: textColorSecondary
                    }
                }
            }
        };

        setChartData(data);
        setChartOptions(options);
    }, []);

    return (
        <Chart type="radar" data={chartData} options={chartOptions} style={{ width: '70%' }} />
    )

}